import SwiftUI

struct Button: View {
    enum Variant: String {
        case primary, secondary, ghost
    }

    enum Size: String {
        case sm, md, lg
    }

    var label: String
    var variant: Variant = .primary
    var size: Size = .md
    var disabled: Bool = false
    var loading: Bool = false
    var icon_leading: String? = nil

    var onPressed: (() -> Void)? = nil
    var onLongPressed: (() -> Void)? = nil

    private var backgroundColor: Color {
        switch variant {
        case .primary: return .blue
        case .secondary: return .gray.opacity(0.2)
        case .ghost: return .clear
        }
    }

    private var foregroundColor: Color {
        switch variant {
        case .primary: return .white
        case .secondary: return .primary
        case .ghost: return .blue
        }
    }

    private var verticalPadding: CGFloat {
        switch size {
        case .sm: return 6
        case .md: return 10
        case .lg: return 14
        }
    }

    private var horizontalPadding: CGFloat {
        switch size {
        case .sm: return 12
        case .md: return 16
        case .lg: return 20
        }
    }

    private var fontSize: CGFloat {
        switch size {
        case .sm: return 13
        case .md: return 15
        case .lg: return 17
        }
    }

    private func handlePress() {
        guard !disabled, !loading else { return }
        onPressed?()
    }

    private func handleLongPress() {
        guard !disabled, !loading else { return }
        onLongPressed?()
    }

    var body: some View {
        SwiftUI.Button(action: handlePress) {
            HStack(spacing: 8) {
                if loading {
                    ProgressView()
                        .progressViewStyle(.circular)
                } else {
                    if let iconName = icon_leading, !iconName.isEmpty {
                        Image(systemName: iconName)
                    }
                    Text(label)
                        .font(.system(size: fontSize, weight: .semibold))
                }
            }
            .padding(.vertical, verticalPadding)
            .padding(.horizontal, horizontalPadding)
            .frame(minWidth: 44)
            .foregroundColor(foregroundColor)
            .background(backgroundColor)
            .cornerRadius(8)
            .opacity(disabled ? 0.5 : 1.0)
        }
        .disabled(disabled || loading)
        .accessibilityLabel(Text(label))
        .accessibilityAddTraits(.isButton)
        .accessibilityHint(loading ? Text("Loading") : Text(""))
        .simultaneousGesture(
            LongPressGesture().onEnded { _ in
                handleLongPress()
            }
        )
    }
}
